      "appearance.sections.atmosphere": "\u062A\u0648\u06A9\u0646\u200C\u0647\u0627\u06CC \u0641\u0636\u0627",
      "appearance.shell.intro": "\u0631\u0646\u06AF \u062A\u0623\u06A9\u06CC\u062F\u060C \u0631\u0641\u062A\u0627\u0631 \u0646\u0648\u0627\u0631 \u06A9\u0646\u0627\u0631\u06CC \u0648 \u0639\u0631\u0636 \u0635\u0641\u062D\u0647. \u067E\u06CC\u0634\u200C\u0641\u0631\u0636 \u067E\u0648\u0631\u062A\u0627\u0644 \u062A\u0627 \u0630\u062E\u06CC\u0631\u0647\u0654 \u062A\u0631\u062C\u06CC\u062D\u0627\u062A \u0634\u062E\u0635\u06CC \u0627\u0639\u0645\u0627\u0644 \u0645\u06CC\u200C\u0634\u0648\u062F. \u0628\u0631\u0627\u06CC \u06CC\u062E\u200C\u0632\u062F\u06AF\u06CC\u060C \u0628\u0627\u0641\u062A \u0648 \u06A9\u0631\u0648\u0645 \u0646\u0627\u0648\u0628\u0631\u06CC \u0627\u0632 \u062A\u0628 \u062A\u0648\u06A9\u0646\u200C\u0647\u0627\u06CC \u0641\u0636\u0627 \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u06A9\u0646\u06CC\u062F.",
      "appearance.shell.accent.title": "\u0631\u0646\u06AF \u062A\u0623\u06A9\u06CC\u062F",
      "appearance.shell.accent.description": "\u062F\u06A9\u0645\u0647\u200C\u0647\u0627\u06CC \u0627\u0635\u0644\u06CC\u060C \u0646\u0627\u0648\u0628\u0631\u06CC \u0641\u0639\u0627\u0644\u060C \u062D\u0644\u0642\u0647\u0654 \u0641\u0648\u06A9\u0648\u0633 \u0648 \u0646\u0634\u0627\u0646 \u0628\u0631\u0646\u062F. \u0633\u0637\u0648\u062D \u0628\u0632\u0631\u06AF \u062E\u0646\u062B\u06CC \u0645\u06CC\u200C\u0645\u0627\u0646\u0646\u062F.",
      "appearance.shell.accent.paletteHint": "\u0628\u0631\u0627\u06CC \u062A\u063A\u06CC\u06CC\u0631 \u0631\u0646\u06AF \u062A\u0623\u06A9\u06CC\u062F\u060C \u067E\u0627\u0644\u062A \u0631\u0627 \u0628\u0627\u0632 \u06A9\u0646\u06CC\u062F.",
