      "profile.modals.accountDetails": "\u062C\u0632\u0626\u06CC\u0627\u062A \u062D\u0633\u0627\u0628",
      "profile.modals.activeSessionsIntro": "\u062F\u0633\u062A\u06AF\u0627\u0647\u200C\u0647\u0627\u06CC \u0648\u0627\u0631\u062F\u0634\u062F\u0647 \u0628\u0647 \u062D\u0633\u0627\u0628 \u062E\u0648\u062F \u0631\u0627 \u0628\u0631\u0631\u0633\u06CC \u06A9\u0646\u06CC\u062F. \u0647\u0631 \u0646\u0634\u0633\u062A \u0646\u0627\u0634\u0646\u0627\u062E\u062A\u0647 \u0631\u0627 \u0644\u063A\u0648 \u06A9\u0646\u06CC\u062F.",
      "profile.modals.changePassword": "\u062A\u063A\u06CC\u06CC\u0631 \u0631\u0645\u0632 \u0639\u0628\u0648\u0631",
      "profile.modals.changePasswordIntro": "\u0631\u0645\u0632 \u0639\u0628\u0648\u0631 \u0641\u0639\u0644\u06CC \u0631\u0627 \u0648\u0627\u0631\u062F \u06A9\u0646\u06CC\u062F \u0648 \u0631\u0645\u0632 \u062C\u062F\u06CC\u062F \u0627\u0646\u062A\u062E\u0627\u0628 \u06A9\u0646\u06CC\u062F. \u067E\u0633 \u0627\u0632 \u062A\u063A\u06CC\u06CC\u0631 \u0645\u0648\u0641\u0642\u060C \u0627\u0632 \u062D\u0633\u0627\u0628 \u062E\u0627\u0631\u062C \u0645\u06CC\u200C\u0634\u0648\u06CC\u062F.",
      "profile.modals.deleteAccount": "\u062D\u0630\u0641 \u062D\u0633\u0627\u0628",
      "profile.modals.deleteAccountAck": "\u0645\u06CC\u200C\u0641\u0647\u0645\u0645 \u06A9\u0647 \u062D\u0630\u0641 \u062D\u0633\u0627\u0628 \u0645\u0646 \u062A\u0645\u0627\u0645 \u062F\u0627\u062F\u0647\u200C\u0647\u0627\u06CC\u0645 \u0631\u0627 \u0627\u0632 \u0627\u06CC\u0646 \u0633\u0627\u0645\u0627\u0646\u0647 \u0628\u0631\u0627\u06CC \u0647\u0645\u06CC\u0634\u0647 \u062D\u0630\u0641 \u0645\u06CC\u200C\u06A9\u0646\u062F.",
      "profile.modals.deleteAccountBody1": "\u0628\u0627 \u062D\u0630\u0641 \u062D\u0633\u0627\u0628\u060C \u062A\u0645\u0627\u0645 \u062F\u0627\u062F\u0647\u200C\u0647\u0627\u06CC \u0630\u062E\u06CC\u0631\u0647\u200C\u0634\u062F\u0647 \u062F\u0631\u0628\u0627\u0631\u0647 \u0634\u0645\u0627 \u062F\u0631 \u0627\u06CC\u0646 \u0633\u0627\u0645\u0627\u0646\u0647 \u0628\u0631\u0627\u06CC \u0647\u0645\u06CC\u0634\u0647 \u062D\u0630\u0641 \u0645\u06CC\u200C\u0634\u0648\u062F. \u0634\u0627\u0645\u0644 \u067E\u0631\u0648\u0641\u0627\u06CC\u0644\u060C \u0646\u0642\u0634\u200C\u0647\u0627\u060C \u0646\u0634\u0633\u062A\u200C\u0647\u0627 \u0648 \u0647\u0631 \u0633\u0627\u0628\u0642\u0647 \u0641\u0639\u0627\u0644\u06CC\u062A \u0645\u0631\u062A\u0628\u0637 \u0628\u0627 \u062D\u0633\u0627\u0628 \u06A9\u0627\u0631\u0628\u0631\u06CC \u0634\u0645\u0627.",
      "profile.modals.deleteAccountBody2": "\u0628\u0644\u0627\u0641\u0627\u0635\u0644\u0647 \u062F\u0633\u062A\u0631\u0633\u06CC \u062E\u0648\u062F \u0631\u0627 \u0627\u0632 \u062F\u0633\u062A \u0645\u06CC\u200C\u062F\u0647\u06CC\u062F \u0648 \u0628\u0639\u062F\u0627\u064B \u0646\u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u06CC\u062F \u0627\u06CC\u0646 \u0627\u0637\u0644\u0627\u0639\u0627\u062A \u0631\u0627 \u0628\u0627\u0632\u06CC\u0627\u0628\u06CC \u06A9\u0646\u06CC\u062F.",
