      "settings.cultures.translationsNote": "\u0628\u0631\u0686\u0633\u0628\u200C\u0647\u0627\u06CC \u0628\u0648\u0645\u06CC \u0627\u0632 \u0628\u0633\u062A\u0647 \u0627\u0635\u0644\u06CC \u0627\u0646\u06AF\u0644\u06CC\u0633\u06CC \u0645\u06CC\u200C\u0622\u06CC\u0646\u062F. \u062A\u063A\u06CC\u06CC\u0631\u0627\u062A \u062F\u0631 \u062A\u0646\u0638\u06CC\u0645\u0627\u062A \u067E\u0644\u062A\u0641\u0631\u0645 \u0630\u062E\u06CC\u0631\u0647 \u0645\u06CC\u200C\u0634\u0648\u0646\u062F.",
      "settings.directSaveNote": "\u062A\u063A\u06CC\u06CC\u0631\u0627\u062A \u0645\u0633\u062A\u0642\u06CC\u0645\u0627\u064B \u062F\u0631 \u067E\u0627\u06CC\u06AF\u0627\u0647 \u062F\u0627\u062F\u0647 \u0630\u062E\u06CC\u0631\u0647 \u0645\u06CC\u200C\u0634\u0648\u0646\u062F.",
      "settings.forms.auth.devNotice": "\u062D\u0627\u0644\u062A \u062A\u0648\u0633\u0639\u0647 \u0648\u0631\u0648\u062F \u0631\u0627 \u0631\u0648\u06CC \u0646\u0627\u0645 \u06A9\u0627\u0631\u0628\u0631\u06CC/\u0631\u0645\u0632 \u0633\u0627\u062F\u0647 \u0646\u06AF\u0647 \u0645\u06CC\u200C\u062F\u0627\u0631\u062F. OTP\u060C \u062F\u0631\u0648\u0627\u0632\u0647\u200C\u0647\u0627\u06CC \u062A\u0623\u06CC\u06CC\u062F \u0648 \u062B\u0628\u062A\u200C\u0646\u0627\u0645 \u0639\u0645\u0648\u0645\u06CC \u062E\u0627\u0645\u0648\u0634 \u0645\u06CC\u200C\u0645\u0627\u0646\u0646\u062F \u0648 \u0628\u0627 \u0631\u0627\u0647\u200C\u0627\u0646\u062F\u0627\u0632\u06CC \u0645\u062C\u062F\u062F \u0633\u0631\u0648\u0631 \u0628\u0627\u0632\u06AF\u0631\u062F\u0627\u0646\u062F\u0647 \u0645\u06CC\u200C\u0634\u0648\u0646\u062F. \u062F\u0631 production \u062F\u0631 \u0635\u0648\u0631\u062A \u0646\u06CC\u0627\u0632 \u0641\u0639\u0627\u0644 \u06A9\u0646\u06CC\u062F.",
      "settings.forms.auth.lockout.enable": "\u0642\u0641\u0644 \u062D\u0633\u0627\u0628",
      "settings.forms.auth.lockout.info": "\u0645\u0633\u062F\u0648\u062F\u0633\u0627\u0632\u06CC \u0645\u0648\u0642\u062A \u0648\u0631\u0648\u062F \u067E\u0633 \u0627\u0632 \u062A\u0644\u0627\u0634\u200C\u0647\u0627\u06CC \u0646\u0627\u0645\u0648\u0641\u0642 \u0645\u06A9\u0631\u0631.",
