      "settings.forms.sessionContext.intro": "\u06AF\u0631\u0648\u0647 \u0627\u0648\u0644 \u0647\u0648\u06CC\u062A Shell \u0627\u0633\u062A: \u0646\u0627\u0645 \u06A9\u0627\u0631\u0628\u0631\u06CC\u060C \u0627\u06CC\u0645\u06CC\u0644\u060C \u0646\u0627\u0645\u060C \u0646\u0627\u0645 \u062E\u0627\u0646\u0648\u0627\u062F\u06AF\u06CC \u0648 \u062A\u0635\u0648\u06CC\u0631 \u067E\u0631\u0648\u0641\u0627\u06CC\u0644 \u0628\u0627 Server \u0648 Client \u0647\u0645\u06CC\u0634\u0647 \u0631\u0648\u0634\u0646 \u0642\u0641\u0644 \u0634\u062F\u0647\u200C\u0627\u0646\u062F. \u0645\u0646\u0627\u0628\u0639 \u0627\u062E\u062A\u06CC\u0627\u0631\u06CC \u067E\u0627\u06CC\u06CC\u0646 \u0631\u0627 \u0645\u06CC\u200C\u062A\u0648\u0627\u0646 toggle \u06A9\u0631\u062F.",
      "settings.forms.sessionContext.loadError": "\u0628\u0627\u0631\u06AF\u0630\u0627\u0631\u06CC \u062A\u0646\u0638\u06CC\u0645\u0627\u062A context \u0646\u0634\u0633\u062A \u0646\u0627\u0645\u0648\u0641\u0642 \u0628\u0648\u062F.",
