      "settings.sections.ai-models.description": "\u0645\u062F\u0644\u200C\u0647\u0627\u06CC \u0647\u0648\u0634 \u0645\u0635\u0646\u0648\u0639\u06CC\u060C \u0627\u0631\u0627\u0626\u0647 \u062F\u0647\u0646\u062F\u06AF\u0627\u0646 \u0648 \u0645\u062D\u062F\u0648\u062F\u06CC\u062A\u200C\u0647\u0627\u06CC \u0646\u0631\u062E.",
      "settings.sections.auth": "\u0627\u062D\u0631\u0627\u0632 \u0647\u0648\u06CC\u062A \u0648 \u0627\u0645\u0646\u06CC\u062A",
