      "settings.sections.eua-assist": "\u06A9\u0645\u06A9 \u0647\u0648\u0634 \u0645\u0635\u0646\u0648\u0639\u06CC \u0628\u0647 \u06A9\u0627\u0631\u0628\u0631 \u0646\u0647\u0627\u06CC\u06CC",
      "settings.sections.eua-assist.description": "\u062F\u0633\u062A\u06CC\u0627\u0631 \u0647\u0648\u0634 \u0645\u0635\u0646\u0648\u0639\u06CC \u06A9\u0627\u0631\u0628\u0631 \u0646\u0647\u0627\u06CC\u06CC\u060C \u06AF\u0632\u06CC\u0646\u0647\u200C\u0647\u0627\u06CC \u062A\u063A\u06CC\u06CC\u0631 \u0648\u0636\u0639\u06CC\u062A\u060C \u0645\u062F\u0644\u200C\u0647\u0627\u06CC \u067E\u06CC\u0634\u200C\u0641\u0631\u0636 \u0648 \u0645\u062D\u062F\u0648\u062F\u06CC\u062A\u200C\u0647\u0627\u06CC \u0627\u06CC\u0645\u0646\u06CC \u0631\u0627 \u067E\u0634\u062A\u06CC\u0628\u0627\u0646\u06CC \u0645\u06CC\u200C\u06A9\u0646\u062F.",
      "settings.sections.feedback": "\u0628\u0627\u0632\u062E\u0648\u0631\u062F",
      "settings.sections.feedback.description": "\u0633\u06CC\u0627\u0633\u062A \u0628\u0627\u0632\u062E\u0648\u0631\u062F \u062A\u0639\u0628\u06CC\u0647\u200C\u0634\u062F\u0647\u060C \u0645\u0648\u0636\u0648\u0639\u0627\u062A\u060C \u0645\u0633\u06CC\u0631\u06CC\u0627\u0628\u06CC \u0648 \u062A\u0646\u0638\u06CC\u0645\u0627\u062A \u062C\u0645\u0639\u200C\u0622\u0648\u0631\u06CC.",
      "settings.sections.identity-providers": "\u0627\u0631\u0627\u0626\u0647 \u062F\u0647\u0646\u062F\u06AF\u0627\u0646 \u0647\u0648\u06CC\u062A",
