      "nav.appearance": "\u0627\u0644\u0645\u0638\u0647\u0631",
      "nav.appearance.description": "\u0627\u0644\u0623\u0644\u0648\u0627\u0646\u060C \u062A\u062E\u0637\u064A\u0637 \u0627\u0644\u0642\u0634\u0631\u0629\u060C \u0633\u0644\u0648\u0643 \u0627\u0644\u0634\u0631\u064A\u0637 \u0627\u0644\u062C\u0627\u0646\u0628\u064A\u060C \u0648\u0631\u0645\u0648\u0632 \u0627\u0644\u0623\u062C\u0648\u0627\u0621.",
      "appearance.sections.ariaLabel": "\u0623\u0642\u0633\u0627\u0645 \u0627\u0644\u0645\u0638\u0647\u0631",
      "appearance.sections.shell": "\u0627\u0644\u0642\u0634\u0631\u0629 \u0648\u0627\u0644\u062A\u062E\u0637\u064A\u0637",
      "appearance.sections.atmosphere": "\u0631\u0645\u0648\u0632 \u0627\u0644\u0623\u062C\u0648\u0627\u0621",
      "appearance.shell.intro": "\u0644\u0648\u0646 \u0627\u0644\u062A\u0645\u064A\u064A\u0632\u060C \u0633\u0644\u0648\u0643 \u0627\u0644\u0634\u0631\u064A\u0637 \u0627\u0644\u062C\u0627\u0646\u0628\u064A\u060C \u0648\u0639\u0631\u0636 \u0627\u0644\u0635\u0641\u062D\u0629. \u062A\u064F\u0637\u0628\u0651\u064E\u0642 \u0627\u0641\u062A\u0631\u0627\u0636\u064A\u0627\u062A \u0627\u0644\u0628\u0648\u0627\u0628\u0629 \u062D\u062A\u0649 \u062A\u062D\u0641\u0638 \u062A\u0641\u0636\u064A\u0644\u0627\u062A\u0643 \u0627\u0644\u0634\u062E\u0635\u064A\u0629. \u0627\u0633\u062A\u062E\u062F\u0645 \u062A\u0628\u0648\u064A\u0628 \u0631\u0645\u0648\u0632 \u0627\u0644\u0623\u062C\u0648\u0627\u0621 \u0644\u0644\u0635\u0642\u064A\u0639 \u0648\u0627\u0644\u0642\u0648\u0627\u0645 \u0648\u0643\u0631\u0648\u0645 \u0627\u0644\u062A\u0646\u0642\u0644.",
      "appearance.shell.accent.title": "\u0644\u0648\u0646 \u0627\u0644\u062A\u0645\u064A\u064A\u0632",
      "appearance.shell.accent.description": "\u0627\u0644\u0623\u0632\u0631\u0627\u0631 \u0627\u0644\u0623\u0633\u0627\u0633\u064A\u0629\u060C \u0627\u0644\u062A\u0646\u0642\u0644 \u0627\u0644\u0646\u0634\u0637\u060C \u062D\u0644\u0642\u0627\u062A \u0627\u0644\u062A\u0631\u0643\u064A\u0632\u060C \u0648\u0627\u0644\u0639\u0644\u0627\u0645\u0629. \u0627\u0644\u0623\u0633\u0637\u062D \u0627\u0644\u0643\u0628\u064A\u0631\u0629 \u062A\u0628\u0642\u0649 \u0645\u062D\u0627\u064A\u062F\u0629.",
      "appearance.shell.accent.paletteHint": "\u0627\u0641\u062A\u062D \u0644\u0648\u062D\u0629 \u0627\u0644\u0623\u0644\u0648\u0627\u0646 \u0644\u062A\u063A\u064A\u064A\u0631 \u0644\u0648\u0646 \u0627\u0644\u062A\u0645\u064A\u064A\u0632.",
      "appearance.shell.loading": "\u062C\u0627\u0631\u064D \u062A\u062D\u0645\u064A\u0644 \u062A\u0641\u0636\u064A\u0644\u0627\u062A \u0627\u0644\u0642\u0634\u0631\u0629\u2026",
      "appearance.shell.userPrefs.title": "\u062A\u0641\u0636\u064A\u0644\u0627\u062A\u0643",
      "appearance.shell.userPrefs.description": "\u062A\u064F\u062D\u0641\u0638 \u0641\u064A \u062D\u0633\u0627\u0628\u0643 \u0628\u0639\u062F \u062A\u0633\u062C\u064A\u0644 \u0627\u0644\u062F\u062E\u0648\u0644. \u0625\u0639\u0627\u062F\u0629 \u0627\u0644\u062A\u0639\u064A\u064A\u0646 \u062A\u0639\u064A\u062F \u0627\u0641\u062A\u0631\u0627\u0636\u064A\u0627\u062A \u0627\u0644\u0628\u0648\u0627\u0628\u0629.",
