      "appearance.shell.userPrefs.startCollapsed.hintDisabled": "\u0639\u0637\u0651\u0644 \u0627\u0644\u0645\u0633\u0624\u0648\u0644 \u062A\u062C\u0627\u0648\u0632\u0627\u062A \u0627\u0644\u0634\u0631\u064A\u0637 \u0627\u0644\u062C\u0627\u0646\u0628\u064A \u0627\u0644\u0634\u062E\u0635\u064A\u0629 \u0644\u0647\u0630\u0647 \u0627\u0644\u0628\u0648\u0627\u0628\u0629.",
      "appearance.shell.userPrefs.startCollapsed.aria": "\u0627\u0644\u0628\u062F\u0621 \u0628\u0627\u0644\u0634\u0631\u064A\u0637 \u0627\u0644\u062C\u0627\u0646\u0628\u064A \u0645\u0637\u0648\u064A\u064B\u0627",
      "appearance.shell.userPrefs.pageWidth": "\u0639\u0631\u0636 \u0627\u0644\u0635\u0641\u062D\u0629",
      "appearance.shell.userPrefs.pageWidth.hintControlled": "\u0645\u0639\u0627\u064A\u0646\u0629 \u0645\u0628\u0627\u0634\u0631\u0629 \u0639\u0644\u0649 \u0627\u0644\u0642\u0634\u0631\u0629\u061B \u0627\u0644\u062D\u0641\u0638 \u064A\u062B\u0628\u062A \u062A\u062C\u0627\u0648\u0632\u0643. \u0639\u0646\u062F\u0645\u0627 \u064A\u0643\u0648\u0646 \u0627\u0644\u0627\u0641\u062A\u0631\u0627\u0636\u064A \u0645\u062D\u062F\u0648\u062F\u064B\u0627\u060C \u0632\u0631 \u0627\u0644\u0639\u0631\u0636 \u0641\u064A \u0627\u0644\u0631\u0623\u0633 \u064A\u0628\u062F\u0651\u0644 \u0627\u0644\u062A\u0648\u0633\u064A\u0639.",
      "appearance.shell.userPrefs.pageWidth.hintFixed": "\u0639\u0631\u0636 \u0627\u0644\u0635\u0641\u062D\u0629 \u062B\u0627\u0628\u062A \u0628\u0633\u064A\u0627\u0633\u0629 \u0627\u0644\u0628\u0648\u0627\u0628\u0629.",
