      "appearance.shell.userPrefs.layout.fluid": "\u0645\u0631\u0646 (\u0639\u0631\u0636 \u0627\u0644\u0645\u062D\u062A\u0648\u0649 \u0643\u0627\u0645\u0644\u064B\u0627)",
