      "operations.logs.clearConfirm": "\u0647\u0644 \u0623\u0646\u062A \u0645\u062A\u0623\u0643\u062F \u0623\u0646\u0643 \u062A\u0631\u064A\u062F \u0645\u0633\u062D \u0643\u0627\u0641\u0629 \u0627\u0644\u0633\u062C\u0644\u0627\u062A\u061F",
      "operations.logs.clearConfirmWarning": "\u0647\u0630\u0627 \u0644\u064A\u0633 \u0627\u0644\u0627\u062D\u062A\u0641\u0627\u0638. \u0641\u0647\u0648 \u064A\u062A\u062C\u0627\u0647\u0644 \u0627\u0644\u0639\u0645\u0631 \u0648\u0627\u0644\u0648\u062C\u0647\u0629\u060C \u0648\u064A\u062D\u0630\u0641 \u0643\u0644 \u0635\u0641 \u0633\u062C\u0644 \u0641\u0639\u0627\u0644 \u0627\u0644\u0622\u0646\u060C \u0648\u0644\u0627 \u064A\u0645\u0643\u0646 \u0627\u0644\u062A\u0631\u0627\u062C\u0639 \u0639\u0646 \u0630\u0644\u0643. \u0644\u0627 \u064A\u062A\u0645 \u062D\u0630\u0641 \u0627\u0644\u0646\u0633\u062E \u0627\u0644\u0645\u0624\u0631\u0634\u0641\u0629.",
      "operations.logs.clearInfo": "\u064A\u062D\u0630\u0641 \u0643\u0644 \u0635\u0641 \u0627\u0644\u0633\u062C\u0644 \u0627\u0644\u0633\u0631\u064A\u0639 \u0641\u064A \u0642\u0627\u0639\u062F\u0629 \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u062A\u0634\u063A\u064A\u0644\u064A\u0629 \u0627\u0644\u0622\u0646. \u0647\u0630\u0647 \u0644\u064A\u0633\u062A \u0645\u0647\u0645\u0629 \u0627\u0644\u0627\u062D\u062A\u0641\u0627\u0638: \u0641\u0647\u064A \u0644\u0627 \u062A\u0633\u062A\u062E\u062F\u0645 \u0627\u0644\u0639\u0645\u0631 \u0623\u0648 \u0627\u0644\u0648\u062C\u0647\u0629. \u062A\u0628\u0642\u0649 \u0627\u0644\u0646\u0633\u062E \u0627\u0644\u0645\u0624\u0631\u0634\u0641\u0629. \u0644\u0627 \u064A\u0645\u0643\u0646 \u0627\u0644\u062A\u0631\u0627\u062C\u0639 \u0639\u0646 \u0647\u0630\u0627.",
      "operations.logs.clearResult": "\u062A\u0645 \u0645\u0633\u062D \u0627\u0644\u0633\u062C\u0644\u0627\u062A \u0627\u0644\u0633\u0627\u062E\u0646\u0629. \u0633\u064A\u062A\u0645 \u0625\u0639\u0627\u062F\u0629 \u062A\u062D\u0645\u064A\u0644 \u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u0628\u062F\u0648\u0646 \u062A\u0644\u0643 \u0627\u0644\u0635\u0641\u0648\u0641 \u0627\u0644\u062A\u0634\u063A\u064A\u0644\u064A\u0629. \u0644\u0645 \u064A\u062A\u0645 \u062D\u0630\u0641 \u0627\u0644\u0646\u0633\u062E \u0627\u0644\u0645\u0624\u0631\u0634\u0641\u0629.",
