      "settings.cultures.translationsNote": "\u062A\u0623\u062A\u064A \u0627\u0644\u062A\u0633\u0645\u064A\u0627\u062A \u0627\u0644\u0623\u0635\u0644\u064A\u0629 \u0645\u0646 \u0627\u0644\u062D\u0632\u0645\u0629 \u0627\u0644\u0625\u0646\u062C\u0644\u064A\u0632\u064A\u0629 \u0627\u0644\u0631\u0626\u064A\u0633\u064A\u0629. \u062A\u064F\u062D\u0641\u0638 \u0627\u0644\u062A\u063A\u064A\u064A\u0631\u0627\u062A \u0641\u064A \u0625\u0639\u062F\u0627\u062F\u0627\u062A \u0627\u0644\u0645\u0646\u0635\u0629.",
      "settings.directSaveNote": "\u062A\u064F\u062D\u0641\u0638 \u0627\u0644\u062A\u063A\u064A\u064A\u0631\u0627\u062A \u0645\u0628\u0627\u0634\u0631\u0629 \u0641\u064A \u0642\u0627\u0639\u062F\u0629 \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A.",
      "settings.forms.auth.devNotice": "\u0648\u0636\u0639 \u0627\u0644\u062A\u0637\u0648\u064A\u0631 \u064A\u0628\u0642\u064A \u062A\u0633\u062C\u064A\u0644 \u0627\u0644\u062F\u062E\u0648\u0644 \u0628\u0627\u0633\u0645 \u0645\u0633\u062A\u062E\u062F\u0645/\u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u0628\u0633\u064A\u0637\u0629. OTP \u0648\u0628\u0648\u0627\u0628\u0627\u062A \u0627\u0644\u062A\u062D\u0642\u0642 \u0648\u0627\u0644\u062A\u0633\u062C\u064A\u0644 \u0627\u0644\u0639\u0627\u0645 \u062A\u0628\u0642\u0649 \u0645\u0639\u0637\u0644\u0629 \u0648\u062A\u064F\u0633\u062A\u0639\u0627\u062F \u0639\u0646\u062F \u0625\u0639\u0627\u062F\u0629 \u062A\u0634\u063A\u064A\u0644 \u0627\u0644\u062E\u0627\u062F\u0645. \u0641\u0639\u0651\u0644\u0647\u0627 \u0641\u064A \u0627\u0644\u0625\u0646\u062A\u0627\u062C \u0639\u0646\u062F \u0627\u0644\u062D\u0627\u062C\u0629.",
      "settings.forms.auth.lockout.enable": "\u0642\u0641\u0644 \u0627\u0644\u062D\u0633\u0627\u0628",
      "settings.forms.auth.lockout.info": "\u062D\u0638\u0631 \u0627\u0644\u062F\u062E\u0648\u0644 \u0645\u0624\u0642\u062A\u064B\u0627 \u0628\u0639\u062F \u0645\u062D\u0627\u0648\u0644\u0627\u062A \u0641\u0627\u0634\u0644\u0629 \u0645\u062A\u0643\u0631\u0631\u0629.",
