  "hwy.membership.wizard.approveSummary.pendingOnApprove": "\u0628\u0627 \u0641\u0634\u0631\u062F\u0646 \xAB\u062A\u0623\u06CC\u06CC\u062F\xBB \u0630\u062E\u06CC\u0631\u0647 \u0645\u06CC\u200C\u0634\u0648\u062F.",
  "hwy.membership.wizard.approveSummary.nakhebinNone": "\u0647\u0646\u0648\u0632 \u067E\u06CC\u0648\u0646\u062F \u0631\u0623\u06CC\u200C\u062F\u0647\u0646\u062F\u0647 \u0627\u0646\u062A\u062E\u0627\u0628 \u0646\u0634\u062F\u0647",
