  "hwy.membership.wizard.referrer.addCheckbox": "\u0627\u0641\u0632\u0648\u062F\u0646 \u0645\u0639\u0631\u0641 \u0628\u0631\u0627\u06CC \u0627\u06CC\u0646 \u0639\u0636\u0648",
  "hwy.membership.wizard.referrer.noReferrerOptional": "\u0645\u0639\u0631\u0641 \u0627\u062E\u062A\u06CC\u0627\u0631\u06CC \u0627\u0633\u062A. \u06AF\u0632\u06CC\u0646\u0647 \u0628\u0627\u0644\u0627 \u0631\u0627 \u0641\u0639\u0627\u0644 \u06A9\u0646\u06CC\u062F \u062A\u0627 \u0642\u0628\u0644 \u0627\u0632 \u062A\u0623\u06CC\u06CC\u062F \u0645\u0639\u0631\u0641 \u0627\u0636\u0627\u0641\u0647 \u0634\u0648\u062F.",
  "hwy.membership.wizard.referrer.chooseMember": "\u0627\u0646\u062A\u062E\u0627\u0628 \u0645\u0639\u0631\u0641 \u0627\u0632 \u0641\u0647\u0631\u0633\u062A \u0627\u0639\u0636\u0627",
  "hwy.membership.wizard.referrer.cancelDiscovered": "\u0644\u063A\u0648 \u0645\u0639\u0631\u0641",
  "hwy.membership.wizard.referrer.sameAsMember": "\u0645\u0639\u0631\u0641 \u0646\u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u062F \u0647\u0645\u0627\u0646 \u0639\u0636\u0648 \u0628\u0627\u0634\u062F.",
